import React, { useState } from "react";
import styled from "styled-components";
import TabBar from "../../components/common/TabBar";
import { AiFillStar } from "react-icons/ai";
import { FiMapPin } from "react-icons/fi";
import ServiceTile from "../../components/common/ServiceTile";
import TextBox from "../../components/common/TextBox";
import Button from "../../components/common/Button";
import errorImage from "../../images/errorLoading.png";

/* ---------- Styled ---------- */
const PageWrapper = styled.div`
  background-color: #f7f1f3;
  min-height: 100vh;
  padding-bottom: 40px;
`;

const ContentWrapper = styled.div`
  width: 90%;
  max-width: 900px;
  margin: 40px auto;
  background-color: #fff;
  border-radius: 16px;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.12);
  overflow: hidden;
`;

const HeaderSection = styled.div`
  padding: 24px;
`;

const TabsRow = styled.div`
  display: flex;
  gap: 20px;
  border-bottom: 1px solid #e5e5e5;
  margin-top: 20px;
`;

const AddButtonWrapper = styled.div`
  text-align: center;
  margin-top: 30px;
`;

/* ---------- Modal ---------- */
const ModalOverlay = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(247, 241, 243, 0.95); /* ✅ soft pink-tinted overlay */
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 1000;
`;

const ModalContent = styled.div`
  background: #ffffff;
  padding: 32px;
  border-radius: 12px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
`;

const Form = styled.form`
  display: flex;
  flex-direction: column;
  gap: 16px;
`;

const ButtonGroup = styled.div`
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 20px;
`;

/* ---------- Component ---------- */
const BusinessServices: React.FC = () => {
  const [activeTab, setActiveTab] = useState("Hair");
  const [imgSrc, setImgSrc] = useState(errorImage);

  const [showModal, setShowModal] = useState(false);
  const [selectedService, setSelectedService] = useState<any>(null);
  const [services, setServices] = useState([
    {
      id: "1",
      name: "Haircut",
      duration: "45 min",
      price: 50,
      description: "Professional haircut service including wash and style",
    },
    {
      id: "2",
      name: "Hair Coloring",
      duration: "2 hrs",
      price: 120,
      description: "Full hair coloring service with premium products",
    },
  ]);

  const [formData, setFormData] = useState({
    name: "",
    duration: "",
    price: "",
    description: "",
  });

  /* ---------- Handlers ---------- */
  const handleAddService = () => {
    setSelectedService(null);
    setFormData({ name: "", duration: "", price: "", description: "" });
    setShowModal(true);
  };

  const handleEditService = (service: any) => {
    setSelectedService(service);
    setFormData({
      name: service.name,
      duration: service.duration,
      price: service.price.toString(),
      description: service.description,
    });
    setShowModal(true);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedService) {
      setServices(
        services.map((s) =>
          s.id === selectedService.id
            ? { ...s, ...formData, price: parseFloat(formData.price) }
            : s
        )
      );
    } else {
      setServices([
        ...services,
        {
          id: (services.length + 1).toString(),
          ...formData,
          price: parseFloat(formData.price),
        },
      ]);
    }
    setShowModal(false);
  };

  const salon = {
    name: "Glamour Beauty Salon",
    location: "Seef, Bahrain",
    hours: "9AM - 10PM, Mon - Sun",
    rating: 4.8,
    reviews: 312,
    description:
      "We offer professional hair, nail, and beauty services using premium products.",
    categories: ["Hair", "Coloring", "Styling", "Nails", "Spa"],
  };

  return (
    <PageWrapper>
      {/* ✅ Business TabBar */}
      <TabBar type="business" />

      {/* Main Content */}
      <ContentWrapper>
        <img
          src={imgSrc}
          alt={salon.name}
          onError={() => setImgSrc(errorImage)}
          style={{ width: "100%", height: "220px", objectFit: "cover" }}
        />

        <HeaderSection>
          {/* Salon Info */}
          <h2 style={{ fontSize: "24px", fontWeight: 700 }}>{salon.name}</h2>

          <div
            style={{
              display: "flex",
              alignItems: "center",
              marginTop: "6px",
              color: "#7A7A7A",
              fontSize: "14px",
            }}
          >
            <FiMapPin size={16} style={{ marginRight: "4px" }} />
            {salon.location}
          </div>

          <div style={{ color: "#7A7A7A", fontSize: "14px", marginTop: "4px" }}>
            {salon.hours}
          </div>

          <div
            style={{
              display: "flex",
              alignItems: "center",
              marginTop: "6px",
              fontSize: "14px",
            }}
          >
            <AiFillStar color="#FFD03F" size={16} style={{ marginRight: "4px" }} />
            <span>{salon.rating}</span>
            <span style={{ color: "#7A7A7A", marginLeft: "4px" }}>
              ({salon.reviews})
            </span>
          </div>

          <p style={{ marginTop: "12px", color: "#555", fontSize: "14px" }}>
            {salon.description}
          </p>

          {/* Tabs */}
          <TabsRow>
            {salon.categories.map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                style={{
                  border: "none",
                  background: "none",
                  fontWeight: 500,
                  color: activeTab === tab ? "#000" : "#7A7A7A",
                  borderBottom:
                    activeTab === tab
                      ? "2px solid #000"
                      : "2px solid transparent",
                  padding: "10px 0",
                  cursor: "pointer",
                }}
              >
                {tab}
              </button>
            ))}
          </TabsRow>

          {/* Services List */}
          <div
            style={{
              marginTop: "20px",
              display: "flex",
              flexDirection: "column",
              gap: "16px",
            }}
          >
            {services.map((service) => (
              <div
                key={service.id}
                onClick={() => handleEditService(service)}
                style={{ cursor: "pointer" }}
              >
                <ServiceTile
                  name={service.name}
                  price={service.price}
                  duration={service.duration}
                  description={service.description}
                />
              </div>
            ))}
          </div>

          {/* Add New Service */}
          <AddButtonWrapper>
            <Button onClick={handleAddService}>+ Add New Service</Button>
          </AddButtonWrapper>
        </HeaderSection>
      </ContentWrapper>

      {/* ✅ Modal */}
      {showModal && (
        <ModalOverlay>
          <ModalContent>
            <h3 style={{ fontSize: "20px", fontWeight: 700, marginBottom: "16px" }}>
              {selectedService ? "Edit Service" : "Add New Service"}
            </h3>

            <Form onSubmit={handleSubmit}>
              <TextBox
                placeholder="Service Name"
                value={formData.name}
                onChange={(e) =>
                  setFormData((p) => ({ ...p, name: e.target.value }))
                }
              />
              <TextBox
                placeholder="Duration (e.g., 45 min)"
                value={formData.duration}
                onChange={(e) =>
                  setFormData((p) => ({ ...p, duration: e.target.value }))
                }
              />
              <TextBox
                placeholder="Price"
                type="number"
                value={formData.price}
                onChange={(e) =>
                  setFormData((p) => ({ ...p, price: e.target.value }))
                }
              />
              <TextBox
                placeholder="Description"
                value={formData.description}
                onChange={(e) =>
                  setFormData((p) => ({ ...p, description: e.target.value }))
                }
              />

              <ButtonGroup>
                <Button
                  variant="secondary"
                  onClick={() => setShowModal(false)}
                  type="button"
                >
                  Cancel
                </Button>
                <Button type="submit" variant="primary">
                  {selectedService ? "Update" : "Add"} Service
                </Button>
              </ButtonGroup>
            </Form>
          </ModalContent>
        </ModalOverlay>
      )}
    </PageWrapper>
  );
};

export default BusinessServices;
